const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=name=>`<svg><use href="#${name}"/></svg>`;
const restaurants=[
{id:1,name:'온담 다이닝',category:'한식',area:'강남',station:'강남역 4번 출구',distance:4,price:45000,capacity:12,room:true,match:98,photo:'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=800&q=85',desc:'정갈한 한식과 따뜻한 대화가 있는 곳',reason:'8명이 여유로운 독립 룸 · 예산에 딱 맞아요',tag:'편안한 한식 다이닝',menu:[['온담 한상 코스',45000],['계절 프리미엄 코스',65000],['한우 육회',28000]]},
{id:2,name:'소요 스키야키',category:'일식',area:'강남',station:'역삼역 3번 출구',distance:6,price:49000,capacity:10,room:true,match:96,photo:'https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=800&q=85',desc:'한 냄비를 나누며 가까워지는 저녁',reason:'조용한 룸 · 모두가 즐기는 코스 구성',tag:'함께 나누는 따뜻한 한 끼',menu:[['소요 스키야키 코스',49000],['한우 스키야키 코스',69000],['모둠 사시미',35000]]},
{id:3,name:'테라스 47',category:'양식',area:'강남',station:'강남역 9번 출구',distance:8,price:42000,capacity:16,room:true,match:93,photo:'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=800&q=85',desc:'와인 한 잔에 이야기가 길어지는 공간',reason:'넓은 단체석 · 취향을 타지 않는 메뉴',tag:'여유로운 유러피언 비스트로',menu:[['쉐어링 디너 세트',42000],['트러플 크림 파스타',24000],['채끝 스테이크',46000]]},
{id:4,name:'담백한상',category:'한식',area:'강남',station:'역삼역 1번 출구',distance:5,price:35000,capacity:20,room:true,match:91,photo:'https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=800&q=85',desc:'재료의 계절을 담은 부담 없는 한상',reason:'넉넉한 예산 · 큰 모임도 편안해요',tag:'계절을 담은 한식 테이블',menu:[['계절 한상',35000],['제철 생선 정식',29000],['수육 한 접시',32000]]},
{id:5,name:'노을 식탁',category:'양식',area:'성수',station:'성수역 3번 출구',distance:5,price:39000,capacity:10,room:true,match:96,photo:'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=800&q=85',desc:'성수의 저녁을 닮은 작은 비스트로',reason:'프라이빗한 공간 · 합리적인 코스 가격',tag:'느긋한 성수의 저녁',menu:[['노을 디너 코스',39000],['버섯 리조또',22000],['스테이크',43000]]},
{id:6,name:'온유정',category:'한식',area:'판교',station:'판교역 2번 출구',distance:7,price:48000,capacity:14,room:true,match:95,photo:'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=800&q=85',desc:'비즈니스 모임에도 어울리는 정갈함',reason:'독립 룸 · 대화를 위한 차분한 분위기',tag:'차분하고 정갈한 한식 코스',menu:[['온유 코스',48000],['수라 코스',68000],['전복 솥밥',28000]]},
{id:7,name:'그린 플레이트',category:'양식',area:'강남',station:'강남역 2번 출구',distance:3,price:25000,capacity:8,room:false,match:88,photo:'https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=800&q=85',desc:'가볍고 산뜻하게 함께하는 식사',reason:'부담 없는 가격 · 역에서 가까워요',tag:'캐주얼한 모임의 시작',menu:[['그린 쉐어링 세트',25000],['시즌 샐러드',16000],['토마토 파스타',19000]]}
];
let noRawFish=false, preferredRoom=false, demoVote=null;
let favorites=new Set(),compared=new Set(),bookings=[],view='discover',cuisine='전체',occasion='팀 회식',filters={area:'강남',people:8,budget:50000,room:true,date:'2026-11-13',time:'18:30'},toastTimer,searchTimer;
try{favorites=new Set(JSON.parse(localStorage.getItem('tablemate-favorites')||'[]'));bookings=JSON.parse(localStorage.getItem('tablemate-bookings')||'[]')}catch(e){}
const money=n=>n.toLocaleString('ko-KR')+'원';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('tablemate-favorites',JSON.stringify([...favorites]));localStorage.setItem('tablemate-bookings',JSON.stringify(bookings))}catch(e){}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function card(r,i){return `<article class="restaurant-card" style="animation-delay:${i*55}ms"><div class="photo" onclick="openDetail(${r.id})"><img src="${r.photo}" alt="${r.name} 분위기 참고 이미지" loading="lazy"><span class="match">${icon('spark')}조건 일치 ${r.match}%</span><button class="favorite ${favorites.has(r.id)?'saved':''}" aria-label="${r.name} ${favorites.has(r.id)?'저장 취소':'저장'}" onclick="event.stopPropagation();toggleFavorite(${r.id})">${icon('heart')}</button><span class="photo-label">${r.tag}</span></div><div class="card-content"><div class="category">${r.category} · ${r.area}<span>예시 식당</span></div><div class="title-row"><h3>${r.name}</h3><button aria-label="${r.name} 상세 보기" onclick="openDetail(${r.id})">↗</button></div><p class="description">${r.desc}</p><div class="price">${money(r.price)}<small>/ 1인 코스</small></div><div class="attributes"><span>${icon('room')}${r.room?'독립 룸':'오픈 테이블'}</span><span>${icon('users')}최대 ${r.capacity}명</span><span>${icon('pin')}도보 ${r.distance}분</span></div><div class="reason">${icon('spark')}<span>${r.reason}</span></div><div class="card-bottom"><label class="compare-toggle"><input type="checkbox" ${compared.has(r.id)?'checked':''} onchange="toggleCompare(${r.id},this)">비교 담기</label><button class="detail-btn" onclick="openDetail(${r.id})">자세히 보기${icon('arrow')}</button></div></div></article>`}
function empty(title,desc,button='조건 다시 설정',action='resetFilters()'){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${desc}</p><button class="primary" onclick="${action}">${button}</button></div>`}
function filtered(){let arr=restaurants.filter(r=>r.area===filters.area&&(!noRawFish||r.category!=='일식')&&r.capacity>=filters.people&&r.price<=filters.budget&&(!filters.room||r.room)&&(cuisine==='전체'||r.category===cuisine));const sort=$('#sort').value;return arr.sort((a,b)=>sort==='price'?a.price-b.price:sort==='distance'?a.distance-b.distance:((preferredRoom?Number(b.room)-Number(a.room):0)||b.match-a.match)).slice(0,3)}
function render(){const results=filtered();$('#restaurantGrid').innerHTML=results.length?results.map(card).join(''):empty('조건에 맞는 자리가 아직 없어요','인원을 줄이거나 예산·룸 조건을 조금 넓혀보세요.');$('#resultCount').textContent=results.length;$('#savedCount').textContent=favorites.size;$('#bookingCount').textContent=bookings.filter(b=>b.status!=='취소됨').length;const saved=restaurants.filter(r=>favorites.has(r.id));$('#savedGrid').innerHTML=saved.length?saved.map(card).join(''):empty('마음에 드는 식당을 모아보세요','식당 카드의 하트를 누르면 이곳에 저장돼요.','식당 둘러보기',"setView('discover')");renderBookings();updateCompare()}
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);persist();render();toast(favorites.has(id)?'저장한 식당에 담았어요.':'저장한 식당에서 뺐어요.')}
function toggleCompare(id,el){if(compared.has(id))compared.delete(id);else if(compared.size<3)compared.add(id);else{if(el)el.checked=false;toast('최대 3곳까지 비교할 수 있어요.');return}render()}
function clearCompare(){compared.clear();render()}
function updateCompare(){$('#compareTray').hidden=!compared.size;$('#compareNumber').textContent=compared.size;$('#compareNames').textContent=[...compared].map(id=>restaurants.find(r=>r.id===id).name).join(' · ')}
function stepPeople(delta){$('#people').value=Math.max(2,Math.min(30,(Number($('#people').value)||8)+delta))}
function applySearch(e){if(e)e.preventDefault();filters={area:$('#location').value,people:Math.max(2,Math.min(30,Number($('#people').value)||8)),budget:Number($('#budget').value),room:$('#room').checked,date:$('#date').value||'2026-11-13',time:$('#time').value};$('#people').value=filters.people;const btn=$('.search-btn');btn.disabled=true;btn.innerHTML=`${icon('spark')}조건에 맞는 테이블을 찾고 있어요`;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{btn.disabled=false;btn.innerHTML=`${icon('spark')}맞춤 식당 찾기${icon('arrow')}`;$('#recommendTitle').textContent=`${filters.people}명 ${occasion}에 어울리는 곳을 골랐어요.`;$('#recommendText').textContent=`1인 ${money(filters.budget)} 이내, ${filters.room?'대화하기 좋은 룸이 있는':'편안한'} 식당을 우선 추천해요.`;$('#areaLabel').textContent=filters.area==='강남'?'강남역·역삼역':filters.area+'역';render();toast(`${filtered().length}곳의 예시 식당을 찾았어요.`)},650)}
function resetFilters(){noRawFish=false;preferredRoom=false;$('#naturalInput').value='';$('#parsedConditions').hidden=true;$('#location').value='강남';$('#people').value=8;$('#budget').value=50000;$('#room').checked=true;$('#date').value='2026-11-13';$('#time').value='18:30';cuisine='전체';$$('.cuisine').forEach(b=>b.classList.toggle('active',b.dataset.cuisine===cuisine));$('#sort').value='match';applySearch()}
function setView(next){view=next;const labels={discover:['모임 찾기','어떤 모임을 준비하고 있나요?','모두가 만족할 자리, 조건에 맞춰 함께 찾아볼게요.'],saved:['저장한 식당','다음 모임이 기다려지는 곳.','마음에 드는 식당을 저장하고, 좋은 사람들과 함께하세요.'],bookings:['예약 관리','모임 준비, 여기서 한눈에.','예약 요청부터 확인할 사항까지 차분하게 정리해요.']};['discover','saved','bookings'].forEach(v=>$('#'+v+'View').hidden=v!==next);$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===next));$('#crumb').textContent=labels[next][0];$('#pageTitle').textContent=labels[next][1];$('#pageSubtitle').textContent=labels[next][2];render();window.scrollTo({top:0,behavior:'smooth'})}
let previousFocus;function showModal(html,wide=false){previousFocus=document.activeElement;$('#modal').classList.toggle('wide',wide);$('#modalContent').innerHTML=html;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('.modal-close').focus()}
function closeModal(){$('#overlay').hidden=true;document.body.style.overflow='';if(previousFocus)previousFocus.focus()}
function openDetail(id){const r=restaurants.find(r=>r.id===id);showModal(`<img class="detail-photo" src="${r.photo}" alt="식당 분위기 참고 이미지"><div class="modal-body"><div class="modal-kicker">${r.category} · ${r.area} · 예시 식당</div><h2>${r.name}</h2><p>${r.desc}<br>${r.station}에서 도보 ${r.distance}분</p><div class="detail-facts"><div><small>1인 코스</small><strong>${money(r.price)}</strong></div><div><small>좌석 유형</small><strong>${r.room?'독립 프라이빗 룸':'오픈 테이블'}</strong></div><div><small>수용 인원</small><strong>최대 ${r.capacity}명</strong></div></div><h3>함께 나눌 메뉴</h3>${r.menu.map(m=>`<div class="menu-row"><span>${m[0]}</span><strong>${money(m[1])}</strong></div>`).join('')}<h3>모임을 위한 체크 포인트</h3><p>• ${r.room?'룸 이용 조건과 최소 주문 금액':'단체석 배치'}는 예약 전 확인이 필요해요.<br>• 알레르기·채식 메뉴와 주차 지원 여부도 함께 문의해보세요.</p><p class="source-note">정보 출처: 프로토타입 예시 데이터 · 실제 식당 정보가 아닙니다.<br>메뉴·가격·룸·예약 가능 여부: 미확인 / 사진: 분위기 참고용 이미지</p><div class="detail-actions"><button class="secondary" onclick="toggleFavorite(${r.id})">저장하기</button><button class="primary" onclick="openReservation(${r.id})">이곳으로 모임 준비${icon('arrow')}</button></div></div>`)}
function openCompare(){if(compared.size<2){toast('비교할 식당을 2곳 이상 담아주세요.');return}const list=[...compared].map(id=>restaurants.find(r=>r.id===id));showModal(`<div class="modal-body"><div class="modal-kicker">A TABLE THAT FITS EVERYONE</div><h2>우리 모임에 더 잘 맞는 곳은?</h2><p>가격과 공간 조건을 한눈에 비교해보세요. 모든 정보는 예시입니다.</p><table class="comparison"><thead><tr><th>비교 항목</th>${list.map(r=>`<th>${r.name}</th>`).join('')}</tr></thead><tbody><tr><td>공간 분위기</td>${list.map(r=>`<td><img src="${r.photo}" alt="${r.name} 참고 이미지"></td>`).join('')}</tr>${[['음식 종류',r=>r.category],['1인 예산',r=>money(r.price)],['예상 총액',r=>money(r.price*filters.people)],['룸',r=>r.room?'독립 룸':'오픈 테이블'],['최대 인원',r=>r.capacity+'명'],['역에서 거리',r=>'도보 '+r.distance+'분']].map(([label,fn])=>`<tr><td>${label}</td>${list.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}<tr><td>팀 투표 데모</td>${list.map(r=>`<td><button class="vote-button ${demoVote===r.id?'selected':''}" onclick="voteFor(${r.id})">${demoVote===r.id?'✓ 선택했어요':'이곳에 한 표'}</button></td>`).join('')}</tr><tr><td></td>${list.map(r=>`<td><button class="primary" onclick="openReservation(${r.id})">모임 준비</button></td>`).join('')}</tr></tbody></table><div class="vote-section"><p>팀 의견을 모으는 투표 흐름을 체험해보세요.<br>투표는 이 화면에서만 반영되며 팀원과 동기화되지 않아요.</p><button class="secondary" onclick="copyCandidateLink()">후보 링크 복사</button></div><p class="source-note">실제 예약 가능 여부 및 룸 이용 조건은 확인되지 않았어요.</p></div>`,true)}
function openReservation(id){const r=restaurants.find(r=>r.id===id);showModal(`<div class="modal-body"><div class="modal-kicker">RESERVATION PREVIEW</div><h2>좋은 모임을 준비해볼까요?</h2><p>예약 요청이 어떻게 진행되는지 경험하는 시뮬레이션입니다.</p><div class="reserve-summary"><strong>${r.name}</strong><br>${safe(filters.date)} · ${safe(filters.time)} · ${filters.people}명<br>예상 식사 금액 <strong>${money(r.price*filters.people)}</strong> <small>(추가 주문 제외)</small></div><form class="reservation-form" onsubmit="submitReservation(event,${id})"><label>모임 이름<input name="meeting" required maxlength="50" value="T07 팀 ${occasion}"></label><label>요청사항<textarea name="note" rows="3" maxlength="300" placeholder="예: 조용한 룸으로 부탁드려요. 채식 메뉴가 1개 필요해요."></textarea></label><p class="source-note">최종 예약은 식당 또는 외부 예약 서비스에서 확인해야 해요.<br>이 데모는 실제 식당으로 요청을 보내지 않으며, 입력 내용은 이 브라우저에만 저장됩니다.</p><button class="primary" type="submit">예약 요청 시뮬레이션${icon('arrow')}</button></form></div>`)}
function submitReservation(e,id){e.preventDefault();const data=new FormData(e.target);const r=restaurants.find(r=>r.id===id);bookings.unshift({id:Date.now(),restaurantId:id,meeting:data.get('meeting'),note:data.get('note'),date:filters.date,time:filters.time,people:filters.people,total:r.price*filters.people,status:'요청 준비됨'});persist();render();showModal(`<div class="modal-body success"><div class="success-icon">${icon('check')}</div><div class="modal-kicker">READY FOR A GOOD TIME</div><h2>모임 준비가 한결 가벼워졌어요.</h2><p><strong>${r.name}</strong> 예약 요청 초안을 저장했어요.<br>실제 예약은 진행되지 않았습니다.</p><button class="primary" onclick="closeModal();setView('bookings')">예약 관리에서 보기${icon('arrow')}</button></div>`)}
function renderBookings(){$('#bookingList').innerHTML=bookings.length?bookings.map(b=>{const r=restaurants.find(r=>r.id===b.restaurantId);if(!r)return'';return `<article class="booking-card"><img src="${r.photo}" alt="${r.name} 참고 이미지"><div><span class="booking-status">${safe(b.status)} · 시뮬레이션</span><h3>${safe(b.meeting)}</h3><p>${r.name} · ${safe(b.date)} ${safe(b.time)} · ${b.people}명</p><p>예상 ${money(b.total)}${b.note?' · '+safe(b.note):''}</p></div><div class="booking-actions"><small>실제 예약이 아닙니다</small>${b.status==='취소됨'?'<span class="booking-status">취소 처리됨</span>':`<button class="secondary" onclick="cancelBooking(${b.id})">요청 취소</button>`}</div></article>`}).join(''):empty('아직 준비 중인 모임이 없어요','마음에 드는 식당을 골라 첫 모임을 준비해보세요.','모임 찾기',"setView('discover')")}
function cancelBooking(id){const b=bookings.find(b=>b.id===id);b.status='취소됨';persist();render();toast('시뮬레이션 예약 요청을 취소했어요.')}
function openHelp(){showModal(`<div class="modal-body"><div class="modal-kicker">WELCOME TO TABLEMATE</div><h2>모임 준비를 세 단계로.</h2><h3>01. 모임 조건 정하기</h3><p>지역, 인원, 날짜와 예산을 고르고 맞춤 식당 찾기를 눌러주세요.</p><h3>02. 후보 식당 비교하기</h3><p>최대 3곳을 비교함에 담아 가격과 공간을 한눈에 비교하세요.</p><h3>03. 예약 요청 초안 만들기</h3><p>식당 상세에서 모임을 준비하면 예약 관리에 초안이 저장돼요.</p><p class="source-note">프로토타입이므로 AI 추천, 식당 데이터, 예약 요청은 모두 예시·시뮬레이션입니다. 실제 식당 조회나 예약 전송은 하지 않습니다.</p></div>`)}
$('#searchForm').addEventListener('submit',applySearch);$('#sort').addEventListener('change',render);$$('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$$('.cuisine').forEach(b=>b.addEventListener('click',()=>{cuisine=b.dataset.cuisine;$$('.cuisine').forEach(x=>x.classList.toggle('active',x===b));render()}));$$('.occasion').forEach(b=>b.addEventListener('click',()=>{occasion=b.dataset.occasion;$$('.occasion').forEach(x=>x.classList.toggle('active',x===b))}));$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#overlay').hidden){const els=[...$('#modal').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});render();

function useExample(){$('#naturalInput').value='목요일 저녁 강남역 근처 8명, 인당 4만 원 이하, 한 명은 회를 못 먹고 룸이면 좋겠어';$('#naturalInput').focus()}
function parseNatural(){const text=$('#naturalInput').value.trim();if(!text){toast('모임 조건을 적거나 예시 조건을 넣어주세요.');return}const people=text.match(/(\d+)\s*명/), budget=text.match(/(\d+(?:\.\d+)?)\s*만\s*원/);if(people)$('#people').value=Math.max(2,Math.min(30,Number(people[1])));if(budget){const val=Number(budget[1])*10000;let option=[...$('#budget').options].find(o=>Number(o.value)===val);if(!option){option=new Option(money(val)+' 이하',val);$('#budget').add(option)}$('#budget').value=val}if(text.includes('성수'))$('#location').value='성수';else if(text.includes('판교'))$('#location').value='판교';else if(text.includes('강남'))$('#location').value='강남';if(text.includes('목요일'))$('#date').value='2026-11-12';if(text.includes('저녁'))$('#time').value='18:30';noRawFish=/회.*(못|안)|날것|해산물.*(못|안)/.test(text);preferredRoom=text.includes('룸');$('#room').checked=text.includes('룸 필수')||text.includes('반드시 룸');$('#parsedConditions').hidden=false;$('#parsedConditions').innerHTML=`<span class="required">필수 · ${$('#people').value}명</span><span class="required">필수 · 인당 ${money(Number($('#budget').value))} 이하</span>${noRawFish?'<span class="required">필수 · 회 중심 메뉴 제외</span>':''}${preferredRoom?'<span>선호 · 프라이빗 룸</span>':''}<span>예시 규칙으로 정리 · 아래에서 수정 가능</span>`;applySearch()}
function voteFor(id){demoVote=demoVote===id?null:id;openCompare();toast(demoVote?'이 식당에 한 표를 남겼어요. (로컬 데모)':'선택을 취소했어요.')}
async function copyCandidateLink(){const url=new URL(location.href);url.searchParams.set('candidates',[...compared].join(','));try{await navigator.clipboard.writeText(url.href);toast('후보 비교 링크를 복사했어요. 투표 결과는 공유되지 않아요.')}catch(e){showModal(`<div class="modal-body"><h2>후보 비교 링크</h2><p>아래 링크를 복사하세요. 투표 결과는 공유되지 않습니다.</p><input style="width:100%;padding:12px" readonly value="${safe(url.href)}" onclick="this.select()"></div>`)}}
const incoming=new URLSearchParams(location.search).get('candidates');if(incoming){compared=new Set(incoming.split(',').map(Number).filter(id=>restaurants.some(r=>r.id===id)).slice(0,3));render();if(compared.size>=2)openCompare()}
